#include <limits>
#include <iostream>

int main() {
    using T = float;
    std::cout << "--- Float Precision ---\n";
    std::cout << "Radix (Base): " << std::numeric_limits<T>::radix << "\n";
    std::cout << "Digits (Mantisssa bits): " << std::numeric_limits<T>::digits << "\n";
    std::cout << "Digits10 (Guaranteed decimal): " << std::numeric_limits<T>::digits10 << "\n";
    std::cout << "Epsilon: " << std::numeric_limits<T>::epsilon() << "\n";

    // Example: Comparing float values using epsilon
    T a = 1.0F; 
    T b = 1.0F + std::numeric_limits<T>::epsilon() / 2.0F;
    if (a == b) {
        std::cout << "A == B (expected based on machine precision)\n";
    }
}
